query:
UPDATE users 
SET avatar_url = REPLACE(avatar_url, '/manus-storage/', '/api/storage/')
WHERE avatar_url LIKE '/manus-storage/%';

UPDATE users 
SET avatar_key = avatar_key
WHERE avatar_url LIKE '/api/storage/%';

SELECT id, email, avatar_url FROM users WHERE avatar_url IS NOT NULL LIMIT 10;

